    case 'ABS': return ns.length === 1 ? num(Math.abs(ns[0])) : err('#ERR!')
    case 'SUM': return fin(ns.reduce((s, x) => s + x, 0))
    case 'AVG': return ns.length ? fin(ns.reduce((s, x) => s + x, 0) / ns.length) : err('#DIV/0!')
