}

function literal(c) {
  if (c === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return num(Number(c))
  if (ERRS.includes(c)) return err(c)
  return text(c)
}

// ---- evaluation
const memo = new Map()
const busy = new Set()
function cellValue(k) {
  if (!cells.has(k)) return num(0)
  if (memo.has(k)) return memo.get(k)
  if (busy.has(k)) return err('#CYCLE!')
  busy.add(k)
  let v
  const c = cells.get(k)
  if (c[0] !== '=') v = literal(c)
  else {
    const f = getParsed(k)
    v = !f || f.misplaced ? err('#ERR!') : evalNode(f.ast)
  }
  busy.delete(k)
  memo.set(k, v)
  return v
}

function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  if (v.t === 's') return err('#VALUE!')
  return v
}
const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
const rank = { n: 0, s: 1, b: 2 }
function cmpStr(a, b) {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 's') return cmpStr(a.v, b.v)
  if (a.t === 'b') return Number(a.v) - Number(b.v)
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

function evalNode(n) {
  switch (n.n) {
    case 'num': return num(n.v)
    case 'bool': return bool(n.v)
    case 'ref': {
      const a = parseAddr(n.w)
      return a ? cellValue(keyOf(a.col, a.row)) : err('#REF!')
    }
    case 'un': {
      const v = toNum(evalNode(n.e))
      if (v.t === 'e') return v
      return num(n.op === '-' ? -v.v : v.v)
    }
    case 'bin': {
      const l = evalNode(n.l), r = evalNode(n.r)
      if (l.t === 'e') return l
      if (r.t === 'e') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const d = compare(l, r)
        return bool({ '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op])
      }
      const a = toNum(l)
      if (a.t === 'e') return a
      const b = toNum(r)
      if (b.t === 'e') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        case '^': return fin(Math.pow(a.v, b.v))
      }
      return err('#ERR!')
    }
    case 'call': return evalCall(n)
  }
  return err('#ERR!')
}

function evalCall(n) {
  const { name, args } = n
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'].includes(name)) return err('#NAME?')
  if (name === 'IF') {
    if (args.length !== 3 || args.some((a) => a.n === 'range')) return err('#ERR!')
    const c = evalNode(args[0])
    if (c.t === 'e') return c
    if (c.t === 's') return err('#VALUE!')
    const truth = c.t === 'b' ? c.v : c.v !== 0
    return evalNode(truth ? args[1] : args[2])
  }
  if (name === 'ABS' ? args.length !== 1 : args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) {
    if (a.n === 'range') {
      const ks = expandRange(a)
      if (!ks) vals.push(err('#REF!'))
      else for (const k of ks) vals.push(cellValue(k))
    } else vals.push(evalNode(a))
  }
  const e = vals.find((v) => v.t === 'e')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
  const ns = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    ns.push(x.v)
  }
  const sum = () => ns.reduce((s, x) => s + x, 0)
  switch (name) {
    case 'ABS': return ns.length === 1 ? num(Math.abs(ns[0])) : err('#ERR!')
    case 'SUM': return fin(sum())
    case 'AVG': return fin(sum() / ns.length)
    case 'MIN': return num(ns.reduce((a, b) => (b < a ? b : a)))
    case 'MAX': return num(ns.reduce((a, b) => (b > a ? b : a)))
  }
  return err('#ERR!')
}

function show(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)) + 0)
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

const keys = [...cells.keys()].sort((a, b) => a - b)
let out = ''
for (const k of keys) {
  if (mode === 'values') out += `${nameOf(k)}=${show(cellValue(k))}\n`
  else {
    const set = new Set()
    const f = cells.get(k)[0] === '=' ? getParsed(k) : null
    if (f) collectDeps(f.ast, set)
    out += `${nameOf(k)}:` + [...set].sort((a, b) => a - b).map((x) => ' ' + nameOf(x)).join('') + '\n'
  }
}
process.stdout.write(out)
